#!/bin/sh
# Regenerates docker/postgres/seed/schema.sql from the updater's Flyway migrations
# (D31, D74). The updater owns the schema (D3); this file is its migrations, in
# version order, so the seed mode builds exactly what Flyway builds.
#
#   sh docker/generate-schema.sh            # updater next to this repo
#   UPDATER_DIR=/path/to/updater sh docker/generate-schema.sh
#
# Then check it: `docker compose down -v && docker compose up -d`, and start the app
# (`ddl-auto=validate`). Commit the regenerated file.
set -eu

cd "$(dirname "$0")/.."
UPDATER_DIR="${UPDATER_DIR:-../japanese-dictionary-updater-component}"
MIGRATIONS="$UPDATER_DIR/src/main/resources/db/migration"
OUT="docker/postgres/seed/schema.sql"

[ -d "$MIGRATIONS" ] || { echo "no Flyway migrations in $MIGRATIONS (set UPDATER_DIR)"; exit 1; }
revision="$(git -C "$UPDATER_DIR" log -1 --format='%h %ad' --date=short -- src/main/resources/db/migration 2>/dev/null || echo unknown)"

{
  echo "-- Mirror of the updater's Postgres schema: its Flyway migrations, concatenated in"
  echo "-- version order. GENERATED by docker/generate-schema.sh; do not edit by hand."
  echo "-- Updater migrations as of commit $revision."
  echo "--"
  echo "-- Used by the seed mode only (docker/postgres/init/01-seed-data.sh). A full load"
  echo "-- starts from an empty database instead, so Flyway can build and record the schema."
  for file in $(ls "$MIGRATIONS"/V*__*.sql | sort -V); do
    echo
    echo "-- ===== $(basename "$file") ====="
    echo
    tr -d '\r' < "$file"
  done
} > "$OUT"

echo "wrote $OUT ($(grep -c '^-- =====' "$OUT") migrations)"
